INSERT INTO simka.master_pembinaan(tingkat,nama_tingkat,min_poin,max_poin,jenis_pembinaan,is_active) VALUES('1','Level 1','5','10','["Membaca istighfar 33 kali","Menyiram tanaman di sekitar sekolah/pesantren","Menghafal mufradat dan menyetorkannya atau mengerjakan tugas tertulis terkait pelanggaran","Tidak mengulangi kesalahan yang sama selama minimal 3 hari","Dan/atau pembinaan lainnya sesuai keputusan pihak terkait"]',true) ON CONFLICT(tingkat) DO NOTHING;
INSERT INTO simka.master_pembinaan(tingkat,nama_tingkat,min_poin,max_poin,jenis_pembinaan,is_active) VALUES('2','Level 2','11','20','["Membaca istighfar 33 kali","Menyiram tanaman di sekitar sekolah/pesantren","Menghafal mufradat dan menyetorkannya atau mengerjakan tugas tertulis terkait pelanggaran","Tidak mengulangi kesalahan yang sama selama minimal 3 hari","Dan/atau pembinaan lainnya sesuai keputusan pihak terkait"]',true) ON CONFLICT(tingkat) DO NOTHING;
INSERT INTO simka.master_pembinaan(tingkat,nama_tingkat,min_poin,max_poin,jenis_pembinaan,is_active) VALUES('3','Level 3','21','30','["Membaca istighfar sehari 100 kali","Menyapu dan mengepel lantai selama 1 hari","Menghafal ayat/hadits atau tugas tertulis terkait pelanggaran","Tidak mengulangi kesalahan serupa selama minimal 1 pekan","Dan/atau pembinaan lainnya sesuai keputusan pihak terkait"]',true) ON CONFLICT(tingkat) DO NOTHING;
INSERT INTO simka.master_pembinaan(tingkat,nama_tingkat,min_poin,max_poin,jenis_pembinaan,is_active) VALUES('4','Level 4','31','34','["Membaca istighfar 300 kali sehari selama 3 hari","Membersihkan kamar mandi selama 1 hari","Menulis ulang dan menghafal ayat/hadits atau mengerjakan tugas praktik/tertulis terkait pelanggaran","Meminta nasihat dan tanda tangan pihak yang ditentukan","Tidak mengulangi kesalahan serupa selama minimal 4 pekan","Dan/atau pembinaan lainnya sesuai keputusan pihak terkait"]',true) ON CONFLICT(tingkat) DO NOTHING;
INSERT INTO simka.master_pembinaan(tingkat,nama_tingkat,min_poin,max_poin,jenis_pembinaan,is_active) VALUES('5','Level 5','35','49','["Membaca istighfar 500 kali sehari selama 3 hari","Membersihkan kamar mandi selama 3–7 hari","Skorsing dengan syarat","Qiyamullail tiga malam yang harus terkonfirmasi","Membuat surat pernyataan","Mendapatkan surat peringatan","Absen rutin minimal 3 hari kepada pihak yang ditentukan","Meminta nasihat dan tanda tangan","Dan/atau pembinaan lainnya sesuai keputusan pihak terkait"]',true) ON CONFLICT(tingkat) DO NOTHING;
INSERT INTO simka.master_pembinaan(tingkat,nama_tingkat,min_poin,max_poin,jenis_pembinaan,is_active) VALUES('6','Level 6','50','69','["Membaca istighfar 500 kali sehari selama 7 hari","Membersihkan kamar mandi selama 5–9 hari","Skorsing dengan syarat","Qiyamullail satu pekan yang harus terkonfirmasi","Membuat surat pernyataan","Mendapatkan surat peringatan","Absen rutin minimal 5 hari kepada pihak yang ditentukan","Meminta nasihat dan tanda tangan","Larangan keluar area pondok sebanyak 1 kali sesuai ketentuan","Gundul atau memakai pakaian pelanggaran","Dan/atau pembinaan lainnya sesuai keputusan pihak terkait"]',true) ON CONFLICT(tingkat) DO NOTHING;
INSERT INTO simka.master_pembinaan(tingkat,nama_tingkat,min_poin,max_poin,jenis_pembinaan,is_active) VALUES('7','Level 7','70','89','["Membaca istighfar 300 kali per hari selama 10 hari","Membersihkan kamar mandi selama 10–14 hari","Skorsing dengan syarat","Qiyamullail satu pekan yang harus terkonfirmasi","Membuat surat pernyataan","Mendapatkan surat peringatan","Absen rutin minimal 10 hari kepada pihak yang ditentukan","Meminta nasihat dan tanda tangan","Larangan keluar area pondok sebanyak 2 kali sesuai ketentuan","Digundul atau memakai pakaian khusus pelanggaran","Dan/atau pembinaan lainnya sesuai keputusan pihak terkait"]',true) ON CONFLICT(tingkat) DO NOTHING;
INSERT INTO simka.master_pembinaan(tingkat,nama_tingkat,min_poin,max_poin,jenis_pembinaan,is_active) VALUES('8','Level 8','90','99','["Membaca istighfar 300 kali per hari selama 14 hari","Membersihkan kamar mandi selama 14 hari","Skorsing tanpa syarat","Qiyamullail satu pekan yang harus terkonfirmasi","Membuat surat pernyataan","Mendapatkan surat peringatan","Absen rutin minimal 14 hari kepada pihak yang ditentukan","Meminta nasihat dan tanda tangan","Larangan keluar area pondok sebanyak 3 kali sesuai ketentuan","Digundul dan memakai pakaian khusus pelanggaran","Dan/atau pembinaan lainnya sesuai keputusan pihak terkait"]',true) ON CONFLICT(tingkat) DO NOTHING;
